function calcular(){var e=parseFloat(document.getElementById("valor1").value),a=parseFloat(document.getElementById("valor2").value),t=document.getElementById("operacao").value,l=0;"soma"===t?l=e+a:"subtracao"===t?l=e-a:"multiplicacao"===t?l=e*a:"divisao"===t&&(l=e/a),document.getElementById("resultado").innerText="Resultado: "+l}